import{_ as e,c as a,a as l,aS as s}from"./chunks/framework.BB9D2qGO.js";const b=JSON.parse('{"title":"MQ","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/MQ.md","filePath":"note/back-end/mianshi/MQ.md","lastUpdated":1756566013000}'),n={name:"note/back-end/mianshi/MQ.md"},i=s(`<h1 id="mq" tabindex="-1">MQ <a class="header-anchor" href="#mq" aria-label="Permalink to &quot;MQ&quot;">​</a></h1><h2 id="rocketmq" tabindex="-1">RocketMQ <a class="header-anchor" href="#rocketmq" aria-label="Permalink to &quot;RocketMQ&quot;">​</a></h2><h3 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h3><ul><li>Topic（主题）</li><li>Queue（队列）：一个Topic由多个Queue组成，消息被均匀地分布在这些Queue中。队列是消息存储和传输的实际载体。</li><li>Consumer Group（消费者组）</li><li>Consumer Instance（消费者实例）</li></ul><p><strong>一个Queue只能被同一个Consumer Group下的一个Consumer Instance消费。但一个Consumer Instance可以同时消费多个Queue。</strong></p><p>队列是什么？和Topic有什么关系？</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>队列（Queue） 是Topic的分区（Partition） 单位。当你创建一个Topic时，必须指定它包含多少个Queue（例如8个、16个）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>消息不是直接存在Topic里的，而是存储在Topic下的各个Queue中。生产者发送消息到某个Topic，这条消息会根据一定的策略（如轮询、哈希）被路由到该Topic下的某一个Queue里。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关系：Topic是逻辑概念，Queue是物理概念。Topic是逻辑上的消息分类，而Queue是实际承载消息的实体。可以把Topic理解成一个由多个Queue组成的逻辑队列。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在创建Topic的时候要指定队列么？</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是的，必须指定。 这是在创建Topic时最重要的参数之一（通常在管理控制台或通过命令创建时指定）。</span></span>
<span class="line"><span>例如，创建命令通常是这样的：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sh mqadmin updateTopic -n 127.0.0.1:9876 -c DefaultCluster -t YOUR_TOPIC_NAME -r 8 -w 8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这里的 -r 8 -w 8 通常就表示读写队列数各为8个。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="rocketmq消费模式有几种" tabindex="-1">RocketMQ消费模式有几种？ <a class="header-anchor" href="#rocketmq消费模式有几种" aria-label="Permalink to &quot;RocketMQ消费模式有几种？&quot;">​</a></h3><p>消费模型由Consumer决定，消费维度为Topic。</p><ol><li>集群消费</li></ol><ul><li>一条消息只会被同Group中的一个Consumer消费</li><li>多个Group同时消费一个Topic时，每个Group都会有一个Consumer消费到数据</li></ul><ol start="2"><li>广播消费</li></ol><p>消息将对一 个Consumer Group 下的各个 Consumer 实例都消费一遍。即即使这些 Consumer 属于同一个Consumer Group ，消息也会被 Consumer Group 中的每个 Consumer 都消费一次。</p><h3 id="rocketmq消费消息是push还是pull" tabindex="-1">RocketMQ消费消息是push还是pull？ <a class="header-anchor" href="#rocketmq消费消息是push还是pull" aria-label="Permalink to &quot;RocketMQ消费消息是push还是pull？&quot;">​</a></h3><p>RocketMQ没有真正意义的push，都是pull，虽然有push类，但实际底层实现采用的是长轮询机制，即拉取方式</p><blockquote><p>broker端属性 longPollingEnable 标记是否开启长轮询。默认开启</p></blockquote><h3 id="一个队列只能被一个同group的消费者实例消费如何理解" tabindex="-1">一个队列只能被一个同Group的消费者实例消费如何理解？ <a class="header-anchor" href="#一个队列只能被一个同group的消费者实例消费如何理解" aria-label="Permalink to &quot;一个队列只能被一个同Group的消费者实例消费如何理解？&quot;">​</a></h3><p>这意味着对于同一个消费者组（Consumer Group）来说，它的所有实例会<strong>共同协商</strong>（通过RocketMQ的负载均衡机制）来分配某个Topic下的所有Queue。</p><ul><li><p><strong>场景一：消费者实例数 = 队列数（理想状态）</strong></p><ul><li>Topic <code>OrderTopic</code> 有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li>你的消费者组 <code>OrderGroup</code> 启动了 4 个实例 (C1, C2, C3, C4)。</li><li>负载均衡后，分配结果是： <ul><li>C1 -&gt; Q1</li><li>C2 -&gt; Q2</li><li>C3 -&gt; Q3</li><li>C4 -&gt; Q4</li></ul></li><li>每个消费者实例都“认领”了一个队列，分工明确，效率最高。</li></ul></li><li><p><strong>场景二：消费者实例数 &lt; 队列数（很常见）</strong></p><ul><li><code>OrderTopic</code> 还是有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li><code>OrderGroup</code> 只启动了 2 个实例 (C1, C2)。</li><li>负载均衡后，分配结果可能是： <ul><li>C1 -&gt; Q1, Q2</li><li>C2 -&gt; Q3, Q4</li></ul></li><li>每个消费者实例需要处理两个队列的消息，只要它们的处理能力跟得上，也没问题。</li></ul></li><li><p><strong>场景三：消费者实例数 &gt; 队列数（资源浪费！）</strong></p><ul><li><code>OrderTopic</code> 只有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li><code>OrderGroup</code> 却启动了 6 个实例 (C1, C2, C3, C4, C5, C6)。</li><li>负载均衡后，分配结果只能是： <ul><li>C1 -&gt; Q1</li><li>C2 -&gt; Q2</li><li>C3 -&gt; Q3</li><li>C4 -&gt; Q4</li><li>C5 -&gt; <strong>（无队列可分配，处于空闲状态）</strong></li><li>C6 -&gt; <strong>（无队列可分配，处于空闲状态）</strong></li></ul></li><li><strong>C5和C6无法消费任何消息，白白浪费了服务器资源。</strong></li></ul></li></ul><hr><h3 id="rocketmq如何保证消息不丢失" tabindex="-1">RocketMQ如何保证消息不丢失？ <a class="header-anchor" href="#rocketmq如何保证消息不丢失" aria-label="Permalink to &quot;RocketMQ如何保证消息不丢失？&quot;">​</a></h3><ol><li>生产者发送消息，失败重试，再失败告警+落库</li><li>broke默认是异步刷盘+集群部署</li><li>消费完成ack确认</li></ol><h3 id="rocketmq的消息堆积如何处理" tabindex="-1">rocketMQ的消息堆积如何处理？ <a class="header-anchor" href="#rocketmq的消息堆积如何处理" aria-label="Permalink to &quot;rocketMQ的消息堆积如何处理？&quot;">​</a></h3><ol><li>修改topic队列数，同时增加消费者数量</li><li>优化代码，提高业务处理速度</li><li>将topic落库或者写脚本转移到一个新的topic中。</li></ol>`,26),o=[i];function r(p,t,u,c,d,h){return l(),a("div",null,o)}const Q=e(n,[["render",r]]);export{b as __pageData,Q as default};
